	private fun parse(): HashMap<Int, Int> {
		val map: HashMap<Int, Int> = HashMap()
		for (pair in TABLE.split(',')) {
			val colon: Int = pair.indexOf(':')
			val id: Int = pair.substring(0, colon).toInt()
			map[id] = pair.substring(colon + 1).toInt()
		}
		return map
	}
